<?php declare(strict_types=1); require __DIR__.'/../config/config.php'; $db=db(); $sales=(float)$db->query("SELECT COALESCE(SUM(total),0) FROM sales WHERE DATE(created_at)=CURDATE()")->fetchColumn(); $paid=(float)$db->query("SELECT COALESCE(SUM(paid),0) FROM sales WHERE DATE(created_at)=CURDATE()")->fetchColumn(); $expenses=(float)$db->query("SELECT COALESCE(SUM(amount),0) FROM expenses WHERE DATE(created_at)=CURDATE()")->fetchColumn(); $profit=(float)$db->query("SELECT COALESCE(SUM(si.line_total-(si.quantity_units*m.purchase_price)),0) FROM sale_items si JOIN medicines m ON m.id=si.medicine_id JOIN sales s ON s.id=si.sale_id WHERE DATE(s.created_at)=CURDATE()")->fetchColumn(); $low=$db->query("SELECT m.name,m.reorder_level,COALESCE(SUM(b.units_remaining),0) stock FROM medicines m LEFT JOIN batches b ON b.medicine_id=m.id WHERE m.active=1 GROUP BY m.id HAVING stock<=m.reorder_level ORDER BY stock")->fetchAll(); $expiry=$db->query("SELECT m.name,b.batch_no,b.expiry_date,b.units_remaining FROM batches b JOIN medicines m ON m.id=b.medicine_id WHERE b.expiry_date IS NOT NULL AND b.expiry_date<=DATE_ADD(CURDATE(),INTERVAL 90 DAY) AND b.units_remaining>0 ORDER BY b.expiry_date")->fetchAll(); ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Reports</title><link rel="stylesheet" href="style.css"></head><body><header><div class="brand">💊 <?=e(APP_NAME)?></div><nav><a href="index.php">Dashboard</a><a href="pos.php">POS</a><a href="inventory.php">Inventory</a><a class="active" href="manage.php">Management</a></nav></header><main><div class="page-title"><div><div class="eyebrow">BUSINESS INTELLIGENCE</div><h1>Reports</h1><p>Today's sales, profit, expenses, stock and expiry alerts.</p></div></div><div class="stats"><div class="stat"><small>Sales</small><b>Rs. <?=money($sales)?></b></div><div class="stat"><small>Collected</small><b>Rs. <?=money($paid)?></b></div><div class="stat"><small>Gross Profit</small><b>Rs. <?=money($profit)?></b></div><div class="stat"><small>Expenses</small><b>Rs. <?=money($expenses)?></b></div></div><section class="panel"><h2>Low Stock</h2><table><tr><th>Medicine</th><th>Stock</th><th>Reorder Level</th></tr><?php foreach($low as $r):?><tr><td><?=e($r['name'])?></td><td><?=number_format((float)$r['stock'])?></td><td><?=number_format((float)$r['reorder_level'])?></td></tr><?php endforeach;?></table></section><section class="panel"><h2>Expiry Within 90 Days</h2><table><tr><th>Medicine</th><th>Batch</th><th>Expiry</th><th>Units</th></tr><?php foreach($expiry as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['batch_no']??'—')?></td><td><?=e($r['expiry_date'])?></td><td><?=number_format((float)$r['units_remaining'])?></td></tr><?php endforeach;?></table></section></main></body></html>